function stripFragment(url) {
	const hash = url.indexOf("#");
	return hash === -1 ? url : url.slice(0, hash);
}

function deepCopy(value) {
	return structuredClone(value);
}

function toResponse(response) {
	return { status: response.status, body: deepCopy(response.body) };
}

export function createClient({ fetchImpl, now = Date.now, ttlMs = undefined } = {}) {
	if (typeof fetchImpl !== "function") throw new TypeError("fetchImpl must be a function");
	if (ttlMs === undefined) ttlMs = 0;
	if (!Number.isInteger(ttlMs) || ttlMs < 0) throw new RangeError("ttlMs must be a non-negative integer");
	const ttl = ttlMs;

	const cache = new Map(); // fragment-less url -> { stamp, status, body }
	const inflight = new Map(); // fragment-less url -> promise of { status, body }
	const counters = { hits: 0, misses: 0, fetches: 0 };

	async function fetchAndStore(key) {
		counters.fetches += 1;
		const response = await fetchImpl(key);
		const stamp = now();
		if (response.status >= 200 && response.status <= 299 && ttl > 0) {
			cache.set(key, { stamp, status: response.status, body: deepCopy(response.body) });
		}
		return toResponse(response);
	}

	return {
		async get(url, options = null) {
			if (typeof url !== "string" || url === "") throw new TypeError("url must be a non-empty string");
			const key = stripFragment(url);
			const fresh = options != null && options.fresh === true;
			if (!fresh) {
				const entry = cache.get(key);
				if (entry) {
					if (now() - entry.stamp < ttl) {
						counters.hits += 1;
						return { status: entry.status, body: deepCopy(entry.body) };
					}
					cache.delete(key); // expired
				}
			}
			counters.misses += 1;
			const pending = inflight.get(key);
			if (!fresh && pending) {
				return toResponse(await pending);
			}
			const promise = fetchAndStore(key);
			inflight.set(key, promise);
			try {
				return toResponse(await promise);
			} finally {
				if (inflight.get(key) === promise) inflight.delete(key);
			}
		},
		clear(url = undefined) {
			if (url === undefined) {
				cache.clear();
				return;
			}
			cache.delete(typeof url === "string" ? stripFragment(url) : url);
		},
		stats() {
			return { hits: counters.hits, misses: counters.misses, fetches: counters.fetches };
		},
	};
}

